insert into public.levytate_apprenticeship_standards (
  id,
  title,
  reference_code,
  version,
  status,
  programme_type,
  route,
  occupational_route,
  level,
  funding_band,
  typical_duration,
  official_url,
  integrated_degree,
  professional_recognition,
  job_titles,
  overview,
  last_updated,
  last_verified,
  last_synced_at,
  source_name,
  source_url,
  created_at,
  updated_at
)
select
  stage.id,
  stage.title,
  stage.reference_code,
  stage.version,
  stage.status,
  stage.programme_type,
  stage.route,
  stage.occupational_route,
  stage.level,
  stage.funding_band,
  stage.typical_duration,
  stage.official_url,
  stage.integrated_degree,
  stage.professional_recognition,
  stage.job_titles,
  stage.overview,
  stage.last_updated,
  stage.last_verified,
  stage.last_synced_at,
  stage.source_name,
  stage.source_url,
  timezone('utc', now()),
  timezone('utc', now())
from levytate_standards_import_stage stage
on conflict (id) do update set
  title = excluded.title,
  reference_code = excluded.reference_code,
  version = excluded.version,
  status = excluded.status,
  programme_type = excluded.programme_type,
  route = excluded.route,
  occupational_route = excluded.occupational_route,
  level = excluded.level,
  funding_band = excluded.funding_band,
  typical_duration = excluded.typical_duration,
  official_url = excluded.official_url,
  integrated_degree = excluded.integrated_degree,
  professional_recognition = excluded.professional_recognition,
  job_titles = excluded.job_titles,
  overview = excluded.overview,
  last_updated = excluded.last_updated,
  last_verified = excluded.last_verified,
  last_synced_at = excluded.last_synced_at,
  source_name = excluded.source_name,
  source_url = excluded.source_url,
  updated_at = timezone('utc', now());

delete from public.levytate_apprenticeship_standards target
where not exists (
  select 1
  from levytate_standards_import_stage stage
  where stage.id = target.id
);

